package com.arena.core.training;
import com.arena.core.entity.*;import com.arena.core.exception.*;import com.arena.core.repository.*;import com.arena.core.service.*;
import jakarta.persistence.EntityManagerFactory;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.*;import org.springframework.data.jpa.repository.config.EnableJpaRepositories;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.orm.jpa.*;import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;import org.springframework.transaction.*;import org.springframework.transaction.annotation.EnableTransactionManagement;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringJUnitConfig(StaffRegistrationConsistencyTest.Config.class)
class StaffRegistrationConsistencyTest {
 @Configuration @EnableTransactionManagement
 @EnableJpaRepositories(basePackages={"com.arena.core.training","com.arena.core.repository"},includeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes={AcademyStaffRepository.class,AppUserRepository.class}))
 static class Config {
  @Bean javax.sql.DataSource dataSource(){return new DriverManagerDataSource("jdbc:h2:mem:staff-registration;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000","sa","");}
  @Bean LocalContainerEntityManagerFactoryBean entityManagerFactory(javax.sql.DataSource ds){var f=new LocalContainerEntityManagerFactoryBean();f.setDataSource(ds);f.setManagedTypes(org.springframework.orm.jpa.persistenceunit.PersistenceManagedTypes.of(AcademyStaff.class.getName(),AppUserEntity.class.getName()));f.setJpaVendorAdapter(new HibernateJpaVendorAdapter());f.setJpaPropertyMap(Map.of("hibernate.hbm2ddl.auto","create-drop","hibernate.physical_naming_strategy","org.hibernate.boot.model.naming.CamelCaseToUnderscoresNamingStrategy"));return f;}
  @Bean PlatformTransactionManager transactionManager(EntityManagerFactory f){return new JpaTransactionManager(f);}
  @Bean JdbcTemplate jdbc(javax.sql.DataSource ds){return new JdbcTemplate(ds);}
  @Bean AcademyAuthorization auth(){return mock(AcademyAuthorization.class);}@Bean CustomerRepository customers(){return mock(CustomerRepository.class);}@Bean KeycloakService identities(){return mock(KeycloakService.class);}@Bean AccountSetupNotification mail(){return mock(AccountSetupNotification.class);}@Bean AuditService audit(){return mock(AuditService.class);}@Bean TrainingBatchRepository batches(){return mock(TrainingBatchRepository.class);}
  @Bean StaffLoginService login(AcademyAuthorization a,CustomerRepository c,AcademyStaffRepository s,AppUserRepository u,KeycloakService k,AccountSetupNotification n,AuditService e,TrainingBatchRepository b){return new StaffLoginService(a,c,s,u,k,n,e,b);}
  @Bean StaffRegistrationService registration(AcademyAuthorization a,CustomerRepository c,AcademyStaffRepository s,AppUserRepository u,StaffLoginService l,KeycloakService k,AuditService e,PlatformTransactionManager t){return new StaffRegistrationService(a,c,s,u,l,k,e,t);}
 }
 @Autowired PlatformTransactionManager transactions;@Autowired StaffRegistrationService service;@Autowired StaffLoginService login;@Autowired AcademyStaffRepository staff;@Autowired AppUserRepository users;@Autowired KeycloakService identities;@Autowired AccountSetupNotification mail;@Autowired AuditService audit;@Autowired AcademyAuthorization auth;@Autowired CustomerRepository customers;@Autowired JdbcTemplate jdbc;
 static Jwt jwt=Jwt.withTokenValue("test").header("alg","none").subject("owner").build();
 record Remote(String id,Long academy,Long member,String email){}Map<String,Remote> remote=new ConcurrentHashMap<>();AtomicInteger created=new AtomicInteger();
 @BeforeEach void setup(){reset(identities,mail,audit,auth,customers);staff.deleteAll();users.deleteAll();remote.clear();created.set(0);
  jdbc.execute("CREATE TABLE IF NOT EXISTS test_clubs(id BIGINT PRIMARY KEY)");jdbc.execute("MERGE INTO test_clubs KEY(id) VALUES(1),(2)");jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS test_staff_request ON academy_staff(academy_id,registration_request_id)");jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS test_staff_username ON academy_staff(login_username)");jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS test_staff_email ON academy_staff(login_email)");jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS test_user_username ON app_user(username)");jdbc.execute("CREATE UNIQUE INDEX IF NOT EXISTS test_user_email ON app_user(email)");
  when(auth.operations(any())).thenAnswer(i->{Jwt j=i.getArgument(0);if(j==null)throw new ArenaOpsException(ErrorCode.ACCESS_DENIED);return actor(j.getSubject().equals("other")?2L:1L);});
  when(customers.findBillingCustomerForUpdate(anyLong())).thenAnswer(i->{Long id=i.getArgument(0);jdbc.queryForObject("SELECT id FROM test_clubs WHERE id=? FOR UPDATE",Long.class,id);return Optional.of(CustomerEntity.builder().id(id).customerName("Club").build());});when(customers.findById(anyLong())).thenAnswer(i->Optional.of(CustomerEntity.builder().id(i.getArgument(0)).customerName("Club").build()));
  doAnswer(i->{String username=i.getArgument(0),email=i.getArgument(1);Long academy=i.getArgument(2),member=i.getArgument(3);var user=remote.get(username);if(user!=null&&!(Objects.equals(user.academy(),academy)&&Objects.equals(user.member(),member)&&user.email().equals(email)))throw new ArenaOpsException(ErrorCode.DUPLICATE_USERNAME);for(var value:remote.values())if(value.email().equals(email)&&!(Objects.equals(value.academy(),academy)&&Objects.equals(value.member(),member)))throw new ArenaOpsException(ErrorCode.DUPLICATE_EMAIL);return null;}).when(identities).validateAcademyStaffIdentifiers(any(),any(),any(),nullable(Long.class));
  when(identities.provisionAcademyStaff(any(),any(),any(),anyLong(),anyLong(),any())).thenAnswer(i->{String username=i.getArgument(0),email=i.getArgument(1);Long academy=i.getArgument(3),id=i.getArgument(4);return remote.computeIfAbsent(username,k->new Remote("subject-"+created.incrementAndGet(),academy,id,email)).id();});
 }
 static AcademyAuthorization.Actor actor(Long id){return new AcademyAuthorization.Actor(AppUserEntity.builder().id(id).username("owner").customerId(id).isActive(true).build(),null,Set.of("OWNER"));}
 StaffRegistrationService.Registration request(){return new StaffRegistrationService.Registration(UUID.randomUUID(),"Coach","coach@example.test","9876543210","COACH","COACH","coach",Set.of("INSTRUCTOR"));}
 void code(ErrorCode expected,Runnable run){assertEquals(expected,assertThrows(ArenaOpsException.class,run::run).getErrorCode());}
 @Test void successfulRegistrationAndIdempotentRetryCreateOneMembershipAndIdentity(){var r=request();var m=service.register(jwt,r);assertTrue(m.isActive());assertEquals("PENDING",m.getLoginState());assertEquals("SENT",m.getNotificationState());assertFalse(users.findById(m.getAppUserId()).orElseThrow().getIsActive());assertEquals(m.getId(),service.register(jwt,r).getId());assertEquals(1,created.get());assertEquals(1,staff.count());assertEquals(1,users.count());verify(mail,times(1)).send(any(),anyInt());}
 @Test void duplicateRealmUsernameOrEmailFailsBeforeAnyStaffPersistence(){remote.put("coach",new Remote("external",99L,99L,"other@example.test"));code(ErrorCode.DUPLICATE_USERNAME,()->service.register(jwt,request()));assertEquals(0,staff.count());remote.clear();remote.put("another",new Remote("external",99L,99L,"coach@example.test"));code(ErrorCode.DUPLICATE_EMAIL,()->service.register(jwt,request()));assertEquals(0,staff.count());verify(identities,never()).provisionAcademyStaff(any(),any(),any(),any(),any(),any());verify(identities,never()).deleteUser(any());}
 @Test void localIdentifiersAreCaseInsensitiveAndMembershipIsNotDuplicated(){users.saveAndFlush(AppUserEntity.builder().username("COACH").email("used@example.test").passwordHash("x").role("STAFF").build());code(ErrorCode.DUPLICATE_USERNAME,()->service.register(jwt,request()));users.deleteAll();users.saveAndFlush(AppUserEntity.builder().username("other").email("COACH@EXAMPLE.TEST").passwordHash("x").role("STAFF").build());code(ErrorCode.DUPLICATE_EMAIL,()->service.register(jwt,request()));assertEquals(0,staff.count());}
 @Test void provisioningFailureLeavesOnlyInactiveRecoverableIntentAndRetrySucceeds(){var r=request();when(identities.provisionAcademyStaff(any(),any(),any(),any(),any(),any())).thenThrow(new ArenaOpsException(ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE));code(ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE,()->service.register(jwt,r));var failed=staff.findAll().get(0);assertFalse(failed.isActive());assertNull(failed.getAppUserId());assertEquals("PROVISIONING_FAILED",failed.getLoginState());assertEquals(0,users.count());doReturn("recovered").when(identities).provisionAcademyStaff(any(),any(),any(),any(),any(),any());assertTrue(service.retry(jwt,failed.getId()).isActive());assertEquals(1,staff.count());}
 @Test void databaseFailureAfterRemoteCreationRollsBackLocalActivationAndRetryReusesOwnedIdentity(){var r=request();doThrow(new org.springframework.dao.DataIntegrityViolationException("simulated persistence failure")).when(audit).record(eq("ACADEMY_STAFF_REGISTRATION_COMPLETED"),any(),any(),any(),any(),any(),any(),any());code(ErrorCode.STAFF_REGISTRATION_UNCERTAIN,()->service.register(jwt,r));assertEquals(1,created.get());assertEquals(0,users.count());var intent=staff.findAll().get(0);assertFalse(intent.isActive());assertNull(intent.getAppUserId());assertEquals(intent.getId(),remote.get("coach").member());reset(audit);var completed=service.register(jwt,r);assertEquals(intent.getId(),completed.getId());assertTrue(completed.isActive());assertEquals(1,created.get());verify(identities,never()).deleteUser(any());}
 @Test void notificationFailureReturnsCommittedMembershipWithExplicitFailedNotification(){doThrow(new ArenaOpsException(ErrorCode.EMAIL_DELIVERY_FAILED)).when(mail).send(any(),anyInt());var r=request();var m=service.register(jwt,r);assertTrue(m.isActive());assertEquals("FAILED",m.getNotificationState());assertEquals("PENDING",m.getLoginState());doNothing().when(mail).send(any(),anyInt());assertEquals(m.getId(),service.register(jwt,r).getId());assertEquals(1,created.get());assertEquals("SENT",staff.findById(m.getId()).orElseThrow().getNotificationState());}
 @Test void sameKeyWithChangedPayloadAndCrossTenantRetryAreRejected(){var r=request();var m=service.register(jwt,r);var changed=new StaffRegistrationService.Registration(r.requestId(),"Different",r.email(),r.phone(),r.role(),r.designation(),r.username(),r.roles());code(ErrorCode.CONFLICT,()->service.register(jwt,changed));var other=Jwt.withTokenValue("other").header("alg","none").subject("other").build();code(ErrorCode.RESOURCE_NOT_FOUND,()->service.retry(other,m.getId()));code(ErrorCode.ACCESS_DENIED,()->service.available(null,new StaffRegistrationService.Availability("coach","coach@example.test",null,null)));}
 @Test void concurrentSameRequestIsIdempotentAndConcurrentNewRequestIsRejected()throws Exception{var r=request();var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<AcademyStaff>>of(()->service.register(jwt,r),()->service.register(jwt,r)));assertEquals(results.get(0).get().getId(),results.get(1).get().getId());assertEquals(1,created.get());assertEquals(1,staff.count());code(ErrorCode.DUPLICATE_USERNAME,()->service.register(jwt,request()));assertEquals(1,staff.count());}finally{pool.shutdownNow();}}
 @Test void availabilityDoesNotProvisionAndOwnedRetryDoesNotReportItselfAsDuplicate(){var r=request();service.available(jwt,new StaffRegistrationService.Availability(r.username(),r.email(),r.requestId(),null));assertEquals(0,staff.count());verify(identities,never()).provisionAcademyStaff(any(),any(),any(),any(),any(),any());var m=service.register(jwt,r);service.available(jwt,new StaffRegistrationService.Availability("COACH","COACH@EXAMPLE.TEST",r.requestId(),null));assertEquals(1,staff.count());assertTrue(staff.findById(m.getId()).orElseThrow().isActive());}

 @Test void databaseFailureBeforeProvisioningCreatesNeitherIdentityNorMembership(){doThrow(new org.springframework.dao.DataIntegrityViolationException("intent failed")).when(audit).record(eq("ACADEMY_STAFF_REGISTRATION_STARTED"),any(),any(),any(),any(),any(),any(),any());code(ErrorCode.STAFF_REGISTRATION_UNCERTAIN,()->service.register(jwt,request()));assertEquals(0,staff.count());assertEquals(0,users.count());assertEquals(0,created.get());}
 @Test void concurrentDifferentRequestKeysDoNotCreateDuplicateMemberships()throws Exception{var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<Object>>of(()->attempt(request()),()->attempt(request())));var values=List.of(results.get(0).get(),results.get(1).get());assertEquals(1,values.stream().filter(AcademyStaff.class::isInstance).count());assertTrue(values.contains(ErrorCode.DUPLICATE_USERNAME));assertEquals(1,staff.count());assertEquals(1,users.count());assertEquals(1,created.get());}finally{pool.shutdownNow();}}
 Object attempt(StaffRegistrationService.Registration r){try{return service.register(jwt,r);}catch(ArenaOpsException ex){return ex.getErrorCode();}}

 @Test void concurrentCrossAcademyEmailReservationCreatesOneIdentityOnly()throws Exception{
  var pool=Executors.newFixedThreadPool(2);var other=Jwt.withTokenValue("other").header("alg","none").subject("other").build();var r=request();var second=new StaffRegistrationService.Registration(UUID.randomUUID(),r.name(),r.email(),r.phone(),r.role(),r.designation(),"other.coach",r.roles());
  try{var results=pool.invokeAll(List.<Callable<Object>>of(()->attempt(r),()->{try{return service.register(other,second);}catch(ArenaOpsException ex){return ex.getErrorCode();}}));var values=List.of(results.get(0).get(),results.get(1).get());assertEquals(1,values.stream().filter(AcademyStaff.class::isInstance).count());assertTrue(values.contains(ErrorCode.DUPLICATE_EMAIL));assertEquals(1,staff.count());assertEquals(1,users.count());assertEquals(1,created.get());}finally{pool.shutdownNow();}
 }

 @Test void personnelRoleRestrictionsAreCheckedBeforeCreatingAnIntent(){doThrow(new ArenaOpsException(ErrorCode.ACCESS_DENIED)).when(auth).personnel(any(),any(),any(),any());code(ErrorCode.ACCESS_DENIED,()->service.register(jwt,request()));assertEquals(0,staff.count());verify(identities,never()).validateAcademyStaffIdentifiers(any(),any(),any(),any());}

 @Test void actualDatabaseUniqueConstraintFailureKeepsExistingAccountAndNewIntentInactive(){
  var r=request();var separate=new org.springframework.transaction.support.TransactionTemplate(transactions);separate.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);
  doAnswer(i->{String username=i.getArgument(0),email=i.getArgument(1);Long academy=i.getArgument(3),id=i.getArgument(4);remote.put(username,new Remote("owned-subject",academy,id,email));created.incrementAndGet();separate.executeWithoutResult(status->users.saveAndFlush(AppUserEntity.builder().username("concurrent-existing-account").email(email).passwordHash("existing").role("STAFF").customerId(2L).build()));return "owned-subject";}).when(identities).provisionAcademyStaff(any(),any(),any(),any(),any(),any());
  code(ErrorCode.STAFF_REGISTRATION_UNCERTAIN,()->service.register(jwt,r));var intent=staff.findAll().get(0);assertFalse(intent.isActive());assertNull(intent.getAppUserId());assertEquals(intent.getId(),remote.get("coach").member());assertEquals(1,users.count());assertEquals("concurrent-existing-account",users.findAll().get(0).getUsername());code(ErrorCode.DUPLICATE_EMAIL,()->service.retry(jwt,intent.getId()));assertEquals(1,created.get());assertFalse(staff.findById(intent.getId()).orElseThrow().isActive());verify(identities,never()).deleteUser(any());
 }
}
